package com.finsight.controller; import com.finsight.domain.User; import com.finsight.service.AuthService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/auth") public class AuthController {final AuthService auth;public AuthController(AuthService a){auth=a;}@PostMapping("/login")public ResponseEntity<?> login(@RequestBody Login r){User u=auth.authenticate(r.email(),r.password());if(u==null)return ResponseEntity.status(401).body(Map.of("message","Invalid email or password"));return ResponseEntity.ok(Map.of("token","demo-token-"+u.getId(),"user",Map.of("id",u.getId(),"email",u.getEmail(),"role",u.getRole())));}record Login(String email,String password){}}
